#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-site-blueprint.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-site-blueprint.mjs
 *
 * @version 2
 * @updated 2026-07-09
 *
 * Enforces SITE_BLUEPRINT.yaml: page-tier surfaces may only be coded after a
 * complete, locked, AIRTIGHT site blueprint exists at <git-root>/docs/site/.
 *
 * Green short-circuits (exit 0):
 *   - .standards/autonomy.yaml sets ui_discipline: none
 *   - no page-tier specs AND no locked blueprint (blueprint absent, or present
 *     but not yet lock-marked = in-progress planning; components/API not gated)
 *
 * When page-tier specs exist, requires the locked blueprint plus per-spec
 * `blueprint_doc:` bindings (doc exists, sections complete, referenced flows
 * exist, ## Data cites no GAP).
 *
 * When the lock marker is present (with or without page specs), the FULL
 * airtightness suite runs (SITE_BLUEPRINT.yaml.airtightness):
 *   A1 core files exist (00-INDEX, 01-DESIGN-LANGUAGE, 02-ROUTES-AND-SHELL,
 *      03-API-BINDINGS, 99-COVERAGE-MATRIX)
 *   A2 zero placeholder text (TBD / TODO / <placeholder>) under docs/site/
 *   A3 every pages/*.md carries all 10 page-template H2s; every flows/*.md
 *      all 6 flow-template H2s
 *   A4 every GAP-<n> cited in pages|flows has a `| GAP-<n> |` row in
 *      03-API-BINDINGS.md; no GAP-NEW survives
 *   A5 every /api/v1/... path cited in pages|flows appears verbatim in
 *      03-API-BINDINGS.md
 *   A6 every flows/<x>.md + pages/<y>.md token under docs/site/ resolves
 *   A7 99-COVERAGE-MATRIX.md contains `unmapped_stories: 0`, references every
 *      page/flow doc, and covers every US-<e>.<n> in
 *      docs/plan/05-USER-STORIES.md when that catalog exists
 *   A8 every Components-table row claiming status `built` cites a repo path
 *      that exists on disk
 *
 * Usage: node verify-site-blueprint.mjs [src-root]   (default src-root: "src")
 * Exit: 0 green / 1 with per-violation lines.
 *
 * Per SITE_BLUEPRINT.yaml.verifier + .airtightness.
 */

import { readFileSync, existsSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";
import { execSync } from "node:child_process";

const RULE_ID = "verify-site-blueprint";
const SRC_ROOT = process.argv[2] || "src";
const CWD = process.cwd();

let gitRoot = CWD;
try {
  gitRoot = execSync("git rev-parse --show-toplevel", { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim();
} catch {
  /* not a git repo — treat cwd as root */
}

const LOCK_MARKER = /<!--\s*blueprint-locked:\s*\d{4}-\d{2}-\d{2}\s+by:(user|agent)\s*-->/;
const PLACEHOLDER = /\b(TBD|TODO)\b|<placeholder>/;
const PAGE_DOC_SECTIONS = [
  "## Purpose", "## Route & access", "## Layout", "## Components", "## Data",
  "## State matrix", "## Interactions", "## Edge cases", "## Accessibility", "## Responsive",
];
const FLOW_DOC_SECTIONS = [
  "## Actors & trigger", "## Preconditions", "## Happy path", "## Branches & failures",
  "## Postconditions", "## Scenario checklist",
];
const violations = [];

// ---------- short-circuit: ui_discipline none ----------
for (const dir of [CWD, gitRoot]) {
  const autonomyPath = join(dir, ".standards", "autonomy.yaml");
  if (existsSync(autonomyPath) && /^\s*ui_discipline:\s*none\b/m.test(readFileSync(autonomyPath, "utf8"))) {
    process.stdout.write(`✅ ${RULE_ID} — ui_discipline: none; n/a — non-UI project.\n`);
    process.exit(0);
  }
}

// ---------- discover page-tier specs ----------
const SKIP_DIRS = new Set(["node_modules", ".next", ".turbo", ".git", "coverage", "dist"]);
function walk(dir, hits = []) {
  let entries;
  try { entries = readdirSync(dir); } catch { return hits; }
  for (const name of entries) {
    if (SKIP_DIRS.has(name)) continue;
    const p = join(dir, name);
    let st;
    try { st = statSync(p); } catch { continue; }
    if (st.isDirectory()) walk(p, hits);
    else if (name === "spec.yaml" && /^\s*tier:\s*page\b/m.test(readFileSync(p, "utf8"))) hits.push(p);
  }
  return hits;
}
const srcAbs = join(CWD, SRC_ROOT);
const pageSpecs = existsSync(srcAbs) ? walk(srcAbs) : [];

const bpRoot = join(gitRoot, "docs", "site");
const indexPath = join(bpRoot, "00-INDEX.md");
const locked = existsSync(indexPath) && LOCK_MARKER.test(readFileSync(indexPath, "utf8"));

if (pageSpecs.length === 0 && !locked) {
  const note = existsSync(bpRoot)
    ? "blueprint present but not yet locked (in-progress planning); no page-tier specs — nothing gated."
    : `no page-tier specs under ${SRC_ROOT}/ and no blueprint; components/API work is not gated.`;
  process.stdout.write(`✅ ${RULE_ID} — ${note}\n`);
  process.exit(0);
}

// ---------- page specs exist: lock is mandatory ----------
if (pageSpecs.length > 0 && !locked) {
  violations.push(`page-tier specs exist but docs/site/00-INDEX.md lacks the lock marker <!-- blueprint-locked: YYYY-MM-DD by:user|agent -->`);
}

// ---------- helpers ----------
function mdFiles(dir) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter((f) => f.endsWith(".md")).map((f) => join(dir, f));
}
const pagesDir = join(bpRoot, "pages");
const flowsDir = join(bpRoot, "flows");
const pageDocs = mdFiles(pagesDir);
const flowDocs = mdFiles(flowsDir);
const allDocs = [...mdFiles(bpRoot), ...pageDocs, ...flowDocs];
const rel = (p) => relative(gitRoot, p);

// ---------- airtightness suite (runs whenever locked) ----------
if (locked) {
  // A1 core files
  const CORE = ["00-INDEX.md", "01-DESIGN-LANGUAGE.md", "02-ROUTES-AND-SHELL.md", "03-API-BINDINGS.md", "99-COVERAGE-MATRIX.md"];
  for (const f of CORE) {
    if (!existsSync(join(bpRoot, f))) violations.push(`A1: missing blueprint core file docs/site/${f}`);
  }

  // A2 placeholders
  for (const p of allDocs) {
    readFileSync(p, "utf8").split("\n").forEach((line, i) => {
      if (PLACEHOLDER.test(line)) violations.push(`A2: placeholder text in ${rel(p)}:${i + 1} — "${line.trim().slice(0, 60)}"`);
    });
  }

  // A3 template sections — all page docs + all flow docs
  for (const p of pageDocs) {
    const doc = readFileSync(p, "utf8");
    for (const sec of PAGE_DOC_SECTIONS) if (!doc.includes(sec)) violations.push(`A3: ${rel(p)} lacks "${sec}"`);
  }
  for (const p of flowDocs) {
    const doc = readFileSync(p, "utf8");
    for (const sec of FLOW_DOC_SECTIONS) if (!doc.includes(sec)) violations.push(`A3: ${rel(p)} lacks "${sec}"`);
  }

  const bindingsPath = join(bpRoot, "03-API-BINDINGS.md");
  const bindings = existsSync(bindingsPath) ? readFileSync(bindingsPath, "utf8") : "";

  // A4 GAP citations + A5 endpoint citations
  for (const p of [...pageDocs, ...flowDocs]) {
    const doc = readFileSync(p, "utf8");
    if (/GAP-NEW/.test(doc)) violations.push(`A4: ${rel(p)} contains draft marker GAP-NEW — assign a real GAP id in 03-API-BINDINGS.md`);
    for (const g of new Set([...doc.matchAll(/GAP-(\d+)/g)].map((m) => m[1]))) {
      if (!bindings.includes(`| GAP-${g} |`)) violations.push(`A4: ${rel(p)} cites GAP-${g} — no such row in 03-API-BINDINGS.md`);
    }
    for (const e of new Set([...doc.matchAll(/\/api\/v1\/[a-zA-Z0-9/_[\]{}|.-]+/g)].map((m) => m[0].replace(/[.,)`]+$/, "")))) {
      if (!bindings.includes(e)) violations.push(`A5: ${rel(p)} cites ${e} — not listed in 03-API-BINDINGS.md`);
    }
  }

  // A6 cross-references
  for (const p of allDocs) {
    const doc = readFileSync(p, "utf8");
    for (const m of new Set([...doc.matchAll(/\b(flows|pages)\/([a-z0-9_-]+\.md)/g)].map((x) => `${x[1]}/${x[2]}`))) {
      if (!existsSync(join(bpRoot, m))) violations.push(`A6: ${rel(p)} references ${m} — file does not exist`);
    }
  }

  // A7 coverage matrix
  const matrixPath = join(bpRoot, "99-COVERAGE-MATRIX.md");
  if (existsSync(matrixPath)) {
    const matrix = readFileSync(matrixPath, "utf8");
    if (!/^unmapped_stories:\s*0\s*$/m.test(matrix)) {
      violations.push(`A7: 99-COVERAGE-MATRIX.md lacks the literal terminal line "unmapped_stories: 0"`);
    }
    for (const p of [...pageDocs, ...flowDocs]) {
      const base = p.split("/").pop();
      if (!matrix.includes(base)) violations.push(`A7: ${rel(p)} is never referenced in 99-COVERAGE-MATRIX.md`);
    }
    const catalogPath = join(gitRoot, "docs", "plan", "05-USER-STORIES.md");
    if (existsSync(catalogPath)) {
      const catalog = readFileSync(catalogPath, "utf8");
      for (const s of new Set([...catalog.matchAll(/^- (US-\d+\.\d+)/gm)].map((m) => m[1]))) {
        if (!matrix.includes(`| ${s} `)) violations.push(`A7: catalog story ${s} has no row in 99-COVERAGE-MATRIX.md`);
      }
    }
  }

  // A8 built-claim paths (brace-globs like ui/{a,b}/ expand to one path per alternative)
  function expandBraces(path) {
    const m = path.match(/^(.*)\{([^}]+)\}(.*)$/);
    if (!m) return [path];
    return m[2].split(",").flatMap((alt) => expandBraces(`${m[1]}${alt.trim()}${m[3]}`));
  }
  for (const p of pageDocs) {
    readFileSync(p, "utf8").split("\n").forEach((line, i) => {
      if (!/\|\s*built\s*\|/.test(line)) return;
      const m = line.match(/`([^`]+\/)`/);
      if (!m) return;
      for (const path of expandBraces(m[1])) {
        if (!existsSync(join(gitRoot, path))) {
          violations.push(`A8: ${rel(p)}:${i + 1} claims built component at ${path} — path does not exist`);
        }
      }
    });
  }
}

// ---------- per page-tier spec bindings ----------
for (const spec of pageSpecs) {
  const specRel = relative(CWD, spec);
  const m = readFileSync(spec, "utf8").match(/^\s*blueprint_doc:\s*(\S+)\s*$/m);
  if (!m) { violations.push(`${specRel} is tier: page but carries no blueprint_doc: binding`); continue; }
  const docPath = join(gitRoot, m[1]);
  if (!existsSync(docPath)) { violations.push(`${specRel} binds blueprint_doc ${m[1]} — file does not exist`); continue; }
  const doc = readFileSync(docPath, "utf8");
  const dataSection = doc.split(/^## Data\s*$/m)[1]?.split(/^## /m)[0] ?? "";
  for (const gap of new Set([...dataSection.matchAll(/GAP-\d+|GAP-NEW/g)].map((x) => x[0]))) {
    violations.push(`${m[1]} ## Data cites ${gap} — the API slice must land before this page is coded`);
  }
}

// ---------- report ----------
if (violations.length > 0) {
  process.stdout.write(`❌ ${RULE_ID} — ${violations.length} violation(s):\n`);
  for (const v of violations) process.stdout.write(`   - ${v}\n`);
  process.exit(1);
}
const mode = locked ? `locked blueprint airtight (${pageDocs.length} pages, ${flowDocs.length} flows)` : "no lock, nothing gated";
process.stdout.write(`✅ ${RULE_ID} — ${mode}; ${pageSpecs.length} page-tier spec(s) checked.\n`);
process.exit(0);
